import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/ModelFreePolicyImprovement.html","title":"ModelFreePolicyImprovement","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.51,"words":154},"filePathRelative":"ModelFreePolicyImprovement.md"}`),a={name:`ModelFreePolicyImprovement.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="modelfreepolicyimprovement" tabindex="-1"><a class="header-anchor" href="#modelfreepolicyimprovement"><span>ModelFreePolicyImprovement</span></a></h1><p>前回<a href="./ModelFreePolicyEvaluation.html">ModelFreePolicyEvaluation</a>をやったので、次にPolicy Improvementを考えたい。</p><p><a href="https://www.youtube.com/watch?v=b_wvosA70f8&amp;list=PLoROMvodv4rN4wG6Nk6sNpTEbuOSosZdX&amp;index=4" target="_blank" rel="noopener noreferrer">Stanford CS234 Reinforcement Learning I Q learning and Function Approximation I 2024 I Lecture 4 - YouTube</a></p><h2 id="policy-improvementの難しさ" tabindex="-1"><a class="header-anchor" href="#policy-improvementの難しさ"><span>Policy Improvementの難しさ</span></a></h2><p><img src="/RandomThoughts/assets/0000-CDRQWCa0.png" alt="imgs/CS234Lec4/0000.png"></p><p><a href="./ModelFreePolicyEvaluation.html">ModelFreePolicyEvaluation</a>でポリシーの良さを評価する事は出来たが、 そのポリシーを改善していく方法を考えるとそんなに簡単では無い。</p><p><a href="./MarkovDecisionProcess.html">MarkovDecisionProcess</a>の時のPolicy Improvementと同じように考えると、arg maxのQを求めたくなるが、モデルフリーの場合Policy Evaluationで求めたQはまだ試した事が無いactionについては知らないのでarg maxを求められない。</p><h2 id="exploration" tabindex="-1"><a class="header-anchor" href="#exploration"><span>Exploration</span></a></h2><p><img src="/RandomThoughts/assets/0001-CunXDxZ6.png" alt="imgs/CS234Lec4/0001.png"></p><h2 id="ε-greedyポリシー" tabindex="-1"><a class="header-anchor" href="#ε-greedyポリシー"><span>ε-greedyポリシー</span></a></h2><p><img src="/RandomThoughts/assets/0002-CPMnRWW2.png" alt="imgs/CS234Lec4/0002.png"></p><h2 id="ε-greedyポリシーでのpolicy-improvementの性質" tabindex="-1"><a class="header-anchor" href="#ε-greedyポリシーでのpolicy-improvementの性質"><span>ε-greedyポリシーでのPolicy Improvementの性質</span></a></h2><p><img src="/RandomThoughts/assets/0003-CRP3CLgf.png" alt="imgs/CS234Lec4/0003.png"></p><h2 id="ε-greedyポリシーをcontrolに使う-mc-control" tabindex="-1"><a class="header-anchor" href="#ε-greedyポリシーをcontrolに使う-mc-control"><span>ε-greedyポリシーをControlに使う(MC Control)</span></a></h2><p><img src="/RandomThoughts/assets/0004-BPlnYX56.png" alt="imgs/CS234Lec4/0004.png"></p><h2 id="glieとε-greedyポリシーでのmc-controlの収束" tabindex="-1"><a class="header-anchor" href="#glieとε-greedyポリシーでのmc-controlの収束"><span>GLIEとε-greedyポリシーでのMC Controlの収束</span></a></h2><p><img src="/RandomThoughts/assets/0005-t3wQbv7-.png" alt="imgs/CS234Lec4/0005.png"></p><h2 id="tdコントロール" tabindex="-1"><a class="header-anchor" href="#tdコントロール"><span>TDコントロール</span></a></h2><p><img src="/RandomThoughts/assets/0006-DJ8hLqAj.png" alt="imgs/CS234Lec4/0006.png"></p><p><a href="./TDLearning.html">TDLearning</a>ではVを推計したが、Qを推計するにはアクションが必要となる。 良く使われるのは以下の二つ。</p><ol><li>SARSA（オンポリシー手法の一つ）</li><li>Q-Learning（オフポリシー手法の一つ）</li></ol><h3 id="sarsa" tabindex="-1"><a class="header-anchor" href="#sarsa"><span>SARSA</span></a></h3><p><a href="./SARSA.html">SARSA</a></p><h3 id="オンポリシーとオフポリシー" tabindex="-1"><a class="header-anchor" href="#オンポリシーとオフポリシー"><span>オンポリシーとオフポリシー</span></a></h3><p><img src="/RandomThoughts/assets/0010-D5_C6mv5.png" alt="imgs/CS234Lec4/0010.png"></p><h2 id="q-learning" tabindex="-1"><a class="header-anchor" href="#q-learning"><span>Q-learning</span></a></h2><p><a href="./QLearning.html">QLearning</a></p><h2 id="value関数の関数近似-vfa" tabindex="-1"><a class="header-anchor" href="#value関数の関数近似-vfa"><span>Value関数の関数近似（VFA）</span></a></h2><p><a href="./Value関数の関数近似.html">Value関数の関数近似</a></p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};